-- Phase 5C (UNAPPLIED): dedicated voucher-admin persistence. Apply only through the approved migration process.
BEGIN;
CREATE TABLE IF NOT EXISTS public.voucher_admin_sessions (telegram_user_id bigint PRIMARY KEY CHECK (telegram_user_id=6396446903),step text NOT NULL,voucher_type text,plan_code text,requested_quantity bigint,starts_at timestamptz,ends_at timestamptz,max_redemptions integer,per_user_limit integer,confirmation_key uuid,batch_reference text,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.voucher_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_reference text NOT NULL UNIQUE CHECK(batch_reference ~ '^VB-[A-F0-9]{12}$'),actor_user_id uuid NOT NULL REFERENCES public.app_users(id),voucher_type text NOT NULL CHECK(voucher_type IN ('PERCENT_30','PERCENT_50','PERCENT_100','LIFETIME')),plan_code text NOT NULL,requested_quantity bigint NOT NULL CHECK(requested_quantity>0),generated_quantity bigint NOT NULL DEFAULT 0,delivered_quantity bigint NOT NULL DEFAULT 0,finalized_quantity bigint NOT NULL DEFAULT 0,failed_quantity bigint NOT NULL DEFAULT 0,progress_cursor bigint NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending_delivery' CHECK(status IN ('pending_delivery','delivering','finalized','cancelled')),confirmation_key uuid NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),finalized_at timestamptz,cancelled_at timestamptz);
ALTER TABLE public.subscription_vouchers ADD COLUMN IF NOT EXISTS voucher_reference text UNIQUE CHECK(voucher_reference ~ '^VV-[A-F0-9]{12}$'),ADD COLUMN IF NOT EXISTS chunk_index bigint,ADD COLUMN IF NOT EXISTS item_index integer,ADD COLUMN IF NOT EXISTS voucher_type text CHECK(voucher_type IN ('PERCENT_30','PERCENT_50','PERCENT_100','LIFETIME')),ADD COLUMN IF NOT EXISTS batch_id uuid REFERENCES public.voucher_batches(id),ADD COLUMN IF NOT EXISTS delivery_pending boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS public.voucher_batch_chunks (batch_id uuid NOT NULL REFERENCES public.voucher_batches(id),chunk_index bigint NOT NULL,generated_count integer NOT NULL DEFAULT 0,delivered_count integer NOT NULL DEFAULT 0,finalized_count integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'pending',PRIMARY KEY(batch_id,chunk_index));
CREATE UNIQUE INDEX IF NOT EXISTS subscription_voucher_chunk_item_idx ON public.subscription_vouchers(batch_id,chunk_index,item_index);
CREATE TABLE IF NOT EXISTS public.voucher_admin_webhook_updates (update_id bigint PRIMARY KEY,processed_at timestamptz NOT NULL DEFAULT now(),outcome text NOT NULL DEFAULT 'received');
CREATE TABLE IF NOT EXISTS public.voucher_batch_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,batch_id uuid NOT NULL REFERENCES public.voucher_batches(id),event_type text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),CHECK(jsonb_typeof(metadata)='object'));
CREATE INDEX IF NOT EXISTS voucher_batches_status_idx ON public.voucher_batches(status,created_at DESC);CREATE INDEX IF NOT EXISTS voucher_admin_sessions_expiry_idx ON public.voucher_admin_sessions(expires_at);CREATE INDEX IF NOT EXISTS subscription_vouchers_batch_idx ON public.subscription_vouchers(batch_id);
ALTER TABLE public.voucher_batch_chunks ENABLE ROW LEVEL SECURITY;ALTER TABLE public.voucher_admin_sessions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.voucher_batches ENABLE ROW LEVEL SECURITY;ALTER TABLE public.voucher_admin_webhook_updates ENABLE ROW LEVEL SECURITY;ALTER TABLE public.voucher_batch_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.voucher_batch_chunks,public.voucher_admin_sessions,public.voucher_batches,public.voucher_admin_webhook_updates,public.voucher_batch_audit FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.voucher_admin_actor() RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE a uuid; BEGIN SELECT id INTO a FROM public.app_users WHERE lower(username)='budi' LIMIT 1; IF a IS NULL THEN RAISE EXCEPTION 'voucher unavailable'; END IF; RETURN a; END $$;
CREATE OR REPLACE FUNCTION public.claim_voucher_admin_webhook_update(p_update_id bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF p_update_id IS NULL THEN RAISE EXCEPTION 'voucher unavailable'; END IF; INSERT INTO public.voucher_admin_webhook_updates(update_id) VALUES(p_update_id) ON CONFLICT DO NOTHING; RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.start_voucher_admin_session(p_telegram_user_id bigint,p_expires_at timestamptz) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF p_telegram_user_id<>6396446903 OR p_expires_at<=now() THEN RAISE EXCEPTION 'voucher unavailable'; END IF; INSERT INTO public.voucher_admin_sessions(telegram_user_id,step,expires_at) VALUES(p_telegram_user_id,'type',p_expires_at) ON CONFLICT(telegram_user_id) DO UPDATE SET step='type',voucher_type=NULL,plan_code=NULL,requested_quantity=NULL,confirmation_key=NULL,expires_at=EXCLUDED.expires_at,updated_at=now(); RETURN jsonb_build_object('started',true); END $$;
CREATE OR REPLACE FUNCTION public.advance_voucher_admin_session(p_telegram_user_id bigint,p_step text,p_voucher_type text,p_plan_code text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF p_telegram_user_id<>6396446903 OR p_step NOT IN ('plan','quantity') OR (p_voucher_type IS NOT NULL AND p_voucher_type NOT IN ('PERCENT_30','PERCENT_50','PERCENT_100','LIFETIME')) THEN RAISE EXCEPTION 'voucher unavailable'; END IF; UPDATE public.voucher_admin_sessions SET step=p_step,voucher_type=COALESCE(p_voucher_type,voucher_type),plan_code=COALESCE(p_plan_code,plan_code),updated_at=now() WHERE telegram_user_id=p_telegram_user_id AND expires_at>now(); IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; RETURN jsonb_build_object('advanced',true); END $$;
CREATE OR REPLACE FUNCTION public.set_voucher_admin_quantity(p_telegram_user_id bigint,p_requested_quantity bigint,p_confirmation_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE s public.voucher_admin_sessions%ROWTYPE; BEGIN IF p_telegram_user_id<>6396446903 OR p_requested_quantity IS NULL OR p_requested_quantity<1 OR p_confirmation_key IS NULL THEN RAISE EXCEPTION 'voucher unavailable'; END IF; UPDATE public.voucher_admin_sessions SET requested_quantity=p_requested_quantity,confirmation_key=p_confirmation_key,step='confirm',updated_at=now() WHERE telegram_user_id=p_telegram_user_id AND step='quantity' AND expires_at>now() RETURNING * INTO s; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; RETURN jsonb_build_object('voucher_type',s.voucher_type,'plan_code',s.plan_code,'confirmation_key',s.confirmation_key); END $$;
CREATE OR REPLACE FUNCTION public.clear_voucher_admin_session(p_telegram_user_id bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF p_telegram_user_id<>6396446903 THEN RAISE EXCEPTION 'voucher unavailable'; END IF; DELETE FROM public.voucher_admin_sessions WHERE telegram_user_id=p_telegram_user_id; RETURN true; END $$;
CREATE OR REPLACE FUNCTION public.create_voucher_admin_batch(p_telegram_user_id bigint,p_confirmation_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE s public.voucher_admin_sessions%ROWTYPE;b public.voucher_batches%ROWTYPE; BEGIN IF p_telegram_user_id<>6396446903 THEN RAISE EXCEPTION 'voucher unavailable'; END IF; SELECT * INTO s FROM public.voucher_admin_sessions WHERE telegram_user_id=p_telegram_user_id AND confirmation_key=p_confirmation_key AND step='confirm' AND expires_at>now() FOR UPDATE; IF s.telegram_user_id IS NULL THEN RAISE EXCEPTION 'voucher unavailable'; END IF; SELECT * INTO b FROM public.voucher_batches WHERE confirmation_key=p_confirmation_key; IF b.id IS NOT NULL THEN RETURN jsonb_build_object('batch_reference',b.batch_reference,'requested_quantity',b.requested_quantity,'voucher_type',b.voucher_type,'plan_code',b.plan_code,'already_exists',true,'progress_cursor',b.progress_cursor); END IF; INSERT INTO public.voucher_batches(batch_reference,actor_user_id,voucher_type,plan_code,requested_quantity,confirmation_key) VALUES('VB-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)),public.voucher_admin_actor(),s.voucher_type,s.plan_code,s.requested_quantity,p_confirmation_key) RETURNING * INTO b; RETURN jsonb_build_object('batch_reference',b.batch_reference,'requested_quantity',b.requested_quantity,'voucher_type',b.voucher_type,'plan_code',b.plan_code); END $$;
CREATE OR REPLACE FUNCTION public.insert_voucher_admin_batch_items(p_batch_reference text,p_chunk_index bigint,p_items jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE;i jsonb; n bigint:=0; BEGIN SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference AND status IN ('pending_delivery','delivering') FOR UPDATE; IF NOT FOUND OR jsonb_typeof(p_items)<>'array' THEN RAISE EXCEPTION 'voucher unavailable'; END IF; FOR i IN SELECT * FROM jsonb_array_elements(p_items) LOOP IF i->>'code_hash' !~ '^[a-f0-9]{64}$' OR i->>'code_hint' !~ '^[A-Z0-9]{4}$' THEN RAISE EXCEPTION 'voucher unavailable'; END IF; INSERT INTO public.subscription_vouchers(voucher_reference,code_hash,code_hint,plan_code,voucher_type,duration_days,max_redemptions,active,batch_id,chunk_index,item_index,delivery_pending,created_by_user_id) VALUES('VV-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)),i->>'code_hash',i->>'code_hint',b.plan_code,b.voucher_type,CASE WHEN b.plan_code='LIFETIME' THEN 1 ELSE 30 END,1,false,b.id,p_chunk_index,n::integer,true,b.actor_user_id) ON CONFLICT(batch_id,chunk_index,item_index) DO NOTHING; n:=n+1; END LOOP; UPDATE public.voucher_batch_chunks SET generated_count=n WHERE batch_id=b.id AND chunk_index=p_chunk_index; UPDATE public.voucher_batches SET generated_quantity=generated_quantity+n,status='delivering' WHERE id=b.id; RETURN jsonb_build_object('inserted',n,'cursor',b.progress_cursor+n); END $$;
CREATE OR REPLACE FUNCTION public.record_voucher_admin_batch_delivery(p_batch_reference text,p_delivered_quantity bigint,p_message_part_count integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE; BEGIN IF p_delivered_quantity<0 OR p_message_part_count<0 THEN RAISE EXCEPTION 'voucher unavailable'; END IF; SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; UPDATE public.voucher_batches SET delivered_quantity=greatest(delivered_quantity,p_delivered_quantity) WHERE id=b.id; INSERT INTO public.voucher_batch_audit(batch_id,event_type,metadata) VALUES(b.id,'delivery_succeeded',jsonb_build_object('delivery_channel','telegram','message_part_count',p_message_part_count)); RETURN jsonb_build_object('recorded',true); END $$;
CREATE OR REPLACE FUNCTION public.finalize_voucher_admin_batch(p_batch_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE; BEGIN SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; IF b.status='finalized' THEN RETURN jsonb_build_object('finalized',true,'already_finalized',true); END IF; IF b.delivered_quantity<>b.generated_quantity OR b.generated_quantity<>b.requested_quantity THEN RAISE EXCEPTION 'voucher unavailable'; END IF; UPDATE public.subscription_vouchers SET active=true,delivery_pending=false WHERE batch_id=b.id AND delivery_pending=true; UPDATE public.voucher_batches SET finalized_quantity=generated_quantity,status='finalized',finalized_at=now() WHERE id=b.id; RETURN jsonb_build_object('finalized',true); END $$;
CREATE OR REPLACE FUNCTION public.cancel_voucher_admin_batch(p_batch_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE; BEGIN SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; UPDATE public.subscription_vouchers SET active=false,delivery_pending=false,revoked_at=coalesce(revoked_at,now()) WHERE batch_id=b.id AND active=false; UPDATE public.voucher_batches SET status='cancelled',cancelled_at=coalesce(cancelled_at,now()) WHERE id=b.id AND status<>'finalized'; RETURN jsonb_build_object('cancelled',true); END $$;
CREATE OR REPLACE FUNCTION public.voucher_admin_command(p_command text,p_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE a uuid;n bigint; BEGIN a:=public.voucher_admin_actor(); IF p_command NOT IN ('daftarvoucher','detailvoucher','nonaktifkanvoucher','auditvoucher','statistiklifetime') THEN RAISE EXCEPTION 'voucher unavailable'; END IF; IF p_command='statistiklifetime' THEN SELECT count(*) INTO n FROM public.user_entitlements WHERE lifetime=true AND status='active'; RETURN jsonb_build_object('message','Statistik Lifetime: pengguna aktif '||n||'. Akses lifetime tidak memiliki batas jumlah pengguna.'); END IF; IF p_command='daftarvoucher' THEN SELECT count(*) INTO n FROM public.subscription_vouchers; RETURN jsonb_build_object('message','Daftar voucher tersedia: '||n||' catatan aman.'); END IF; IF p_command='detailvoucher' AND (p_reference IS NULL OR p_reference !~ '^(VB|VV)-[A-F0-9]{12}$') THEN RETURN jsonb_build_object('message','Referensi voucher tidak valid.'); END IF; IF p_command='nonaktifkanvoucher' AND p_reference IS NOT NULL THEN UPDATE public.subscription_vouchers SET active=false,revoked_at=coalesce(revoked_at,now()) WHERE code_hint=p_reference; RETURN jsonb_build_object('message','Permintaan penonaktifan diproses.'); END IF; RETURN jsonb_build_object('message','Audit voucher tidak menampilkan kode, hash, atau identitas.'); END $$;
CREATE OR REPLACE FUNCTION public.claim_voucher_admin_batch_chunk(p_batch_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE;c public.voucher_batch_chunks%ROWTYPE; n integer; BEGIN SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; IF b.finalized_quantity>=b.requested_quantity THEN RETURN jsonb_build_object('done',true); END IF; n:=b.progress_cursor/100; INSERT INTO public.voucher_batch_chunks(batch_id,chunk_index,status) VALUES(b.id,n,'claimed') ON CONFLICT(batch_id,chunk_index) DO NOTHING RETURNING * INTO c; IF c.batch_id IS NULL THEN RETURN jsonb_build_object('done',true); END IF; RETURN jsonb_build_object('chunk_index',n,'count',least(100,b.requested_quantity-b.progress_cursor)); END $$;
CREATE OR REPLACE FUNCTION public.finalize_voucher_admin_batch_chunk(p_batch_reference text,p_chunk_index bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE;c public.voucher_batch_chunks%ROWTYPE; BEGIN SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference FOR UPDATE; SELECT * INTO c FROM public.voucher_batch_chunks WHERE batch_id=b.id AND chunk_index=p_chunk_index FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; IF c.status='finalized' THEN RETURN jsonb_build_object('complete',b.finalized_quantity>=b.requested_quantity); END IF; UPDATE public.subscription_vouchers SET active=true,delivery_pending=false WHERE batch_id=b.id AND chunk_index=p_chunk_index AND delivery_pending=true; UPDATE public.voucher_batch_chunks SET status='finalized',finalized_count=generated_count,delivered_count=generated_count WHERE batch_id=b.id AND chunk_index=p_chunk_index; UPDATE public.voucher_batches SET finalized_quantity=finalized_quantity+c.generated_count,delivered_quantity=delivered_quantity+c.generated_count,progress_cursor=progress_cursor+c.generated_count,status=CASE WHEN finalized_quantity+c.generated_count>=requested_quantity THEN 'finalized' ELSE 'delivering' END WHERE id=b.id RETURNING * INTO b; RETURN jsonb_build_object('complete',b.finalized_quantity>=b.requested_quantity); END $$;
CREATE OR REPLACE FUNCTION public.cancel_voucher_admin_batch_chunk(p_batch_reference text,p_chunk_index bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN UPDATE public.voucher_batch_chunks SET status='cancelled' WHERE chunk_index=p_chunk_index AND batch_id=(SELECT id FROM public.voucher_batches WHERE batch_reference=p_batch_reference); RETURN jsonb_build_object('cancelled',true); END $$;
CREATE OR REPLACE FUNCTION public.get_voucher_admin_batch_progress(p_batch_reference text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE b public.voucher_batches%ROWTYPE; BEGIN SELECT * INTO b FROM public.voucher_batches WHERE batch_reference=p_batch_reference; IF NOT FOUND THEN RAISE EXCEPTION 'voucher unavailable'; END IF; RETURN jsonb_build_object('batch_reference',b.batch_reference,'requested_quantity',b.requested_quantity,'voucher_type',b.voucher_type,'plan_code',b.plan_code,'progress_cursor',b.progress_cursor,'generated_quantity',b.generated_quantity,'delivered_quantity',b.delivered_quantity,'finalized_quantity',b.finalized_quantity); END $$;
REVOKE ALL ON FUNCTION public.voucher_admin_actor(),public.claim_voucher_admin_webhook_update(bigint),public.start_voucher_admin_session(bigint,timestamptz),public.advance_voucher_admin_session(bigint,text,text,text),public.set_voucher_admin_quantity(bigint,bigint,uuid),public.clear_voucher_admin_session(bigint),public.create_voucher_admin_batch(bigint,uuid),public.insert_voucher_admin_batch_items(text,bigint,jsonb),public.record_voucher_admin_batch_delivery(text,bigint,integer),public.finalize_voucher_admin_batch(text),public.cancel_voucher_admin_batch(text),public.voucher_admin_command(text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.voucher_admin_actor(),public.claim_voucher_admin_webhook_update(bigint),public.start_voucher_admin_session(bigint,timestamptz),public.advance_voucher_admin_session(bigint,text,text,text),public.set_voucher_admin_quantity(bigint,bigint,uuid),public.clear_voucher_admin_session(bigint),public.create_voucher_admin_batch(bigint,uuid),public.insert_voucher_admin_batch_items(text,bigint,jsonb),public.record_voucher_admin_batch_delivery(text,bigint,integer),public.finalize_voucher_admin_batch(text),public.cancel_voucher_admin_batch(text),public.voucher_admin_command(text,text),public.claim_voucher_admin_batch_chunk(text),public.finalize_voucher_admin_batch_chunk(text,bigint),public.cancel_voucher_admin_batch_chunk(text,bigint),public.get_voucher_admin_batch_progress(text) TO service_role;
COMMIT;
